using RenewalReviewBuilder.App.Models.History;
namespace RenewalReviewBuilder.App.Services.ClientHistory;
public sealed class HistoryEvolutionService : IHistoryEvolutionService
{
    public IReadOnlyList<ClientHistoryEventReadModel> BuildEvolution(IEnumerable<ClientHistoryEventReadModel> events) => events.Where(e => !e.IsExcluded && e.ChangeSet.Changes.Count > 0).OrderBy(e => e.EffectiveDate).ToList();
    public IReadOnlyList<HistoryEvolutionTrack> BuildTracks(IEnumerable<ClientHistoryEventReadModel> events, string area = "All benefit areas", DateOnly? from = null, DateOnly? to = null) => events.Where(e => !e.IsExcluded && e.ChangeSet.Changes.Count > 0 && (area == "All benefit areas" || e.Category.Equals(area,StringComparison.OrdinalIgnoreCase))).Where(e => !from.HasValue || !e.EffectiveDate.HasValue || e.EffectiveDate >= from).Where(e => !to.HasValue || !e.EffectiveDate.HasValue || e.EffectiveDate <= to).SelectMany(e => e.ChangeSet.Changes.Select(c => (Event:e, Change:c))).GroupBy(x => Subject(x.Change),StringComparer.OrdinalIgnoreCase).Select(g => new HistoryEvolutionTrack { Subject=g.Key, Steps=g.OrderBy(x=>x.Event.EffectiveDate).ThenBy(x=>x.Event.EventId).Select(x=>new HistoryEvolutionStep { EventId=x.Event.EventId, EffectiveDate=x.Event.EffectiveDate, PreviousValue=x.Change.PreviousValue, NewValue=x.Change.NewValue, Unit=x.Change.Unit, Direction=Direction(x.Change), RelatedRenewal=x.Event.RelatedRecords.FirstOrDefault(r=>r.Contains("Renewal",StringComparison.OrdinalIgnoreCase)) ?? "", EvidenceCount=x.Event.Evidence.Count }).ToList() }).OrderBy(t=>t.Subject).ToList();
    private static string Subject(HistoryChangeItem item) => string.IsNullOrWhiteSpace(item.DisplayLabel) ? item.FieldKey : item.DisplayLabel;
    private static string Direction(HistoryChangeItem item) => string.IsNullOrWhiteSpace(item.PreviousValue) ? "Established" : string.IsNullOrWhiteSpace(item.NewValue) ? "Removed" : item.PreviousValue == item.NewValue ? "Unchanged" : "Changed";
}
